      "meaning": "Пористость пласта как линейная функция давления; коэффициент β_c задаёт упругость скелета.",
      "variables": [
        {"symbol": "m", "meaning": "пористость (доля объёма породы, занятая порами)", "unit": "безразмерная"},
        {"symbol": "m0", "meaning": "пористость при опорном давлении p0", "unit": "безразмерная"},
        {"symbol": "β_c", "meaning": "коэффициент объёмной упругости твёрдого скелета пласта", "unit": "1/Па"},
        {"symbol": "p", "meaning": "пластовое давление", "unit": "Па"},
